<?php
declare(strict_types=1);
require_once __DIR__.'/../config/bootstrap.php';require_once __DIR__.'/../config/governance.php';require_once __DIR__.'/../config/privacy.php';
$admin=require_permission($pdo,'privacy.review');$pageTitle='Datenschutzanträge';$error='';
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){require_csrf();try{privacy_review_deletion($pdo,(int)$admin['id'],(int)post_string('request_id'),post_string('decision'),post_string('reason',16000),($_POST['retention_confirmed']??'')==='1');redirect('/admin/privacy.php?saved=1');}catch(InvalidArgumentException|DomainException $e){http_response_code(422);$error=$e->getMessage();}}
$requests=$pdo->query("SELECT r.*,u.username FROM market_deletion_requests r JOIN users u ON u.id=r.user_id ORDER BY CASE r.status WHEN 'pending_review' THEN 0 WHEN 'waiting_retention' THEN 1 ELSE 2 END,r.id DESC LIMIT 100")->fetchAll();include __DIR__.'/../includes/header.php';?>
<main class="container admin-page"><div class="page-heading"><p class="eyebrow">Zweckbindung und Aufbewahrung</p><h1>Datenschutzanträge prüfen.</h1><p>Deaktivierung, Anonymisierung und gesetzlich notwendige Aufbewahrung sind getrennte Schritte. Keine verdeckte Löschung von Zahlungs- oder Auktionsnachweisen.</p></div><div class="admin-layout"><?php include __DIR__.'/../includes/admin-nav.php';?><div class="admin-content">
<?php if($error):?><p class="notice error"><?=h($error)?></p><?php endif;?><?php if(isset($_GET['saved'])):?><p class="notice success">Die Entscheidung wurde dokumentiert.</p><?php endif;?>
<?php foreach($requests as $request):?><section class="panel"><h2>Antrag #<?=(int)$request['id']?> · <?=h($request['username'])?></h2><p>Status <?=h($request['status'])?> · <?=h($request['created_at'])?> UTC</p><p><?=nl2br(h($request['request_reason']))?></p><?php if($request['review_reason']):?><p><?=nl2br(h($request['review_reason']))?></p><?php endif;?>
<?php if($request['status']!=='anonymized'):?><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="request_id" value="<?=(int)$request['id']?>"><label class="field">Entscheidung<select name="decision"><option value="waiting_retention">Aufbewahrung / offene Pflichten klären</option><option value="anonymized">Kontoprofil anonymisieren, notwendige Nachweise erhalten</option></select></label><label class="field">Begründung und Fristenentscheidung<textarea name="reason" minlength="20" maxlength="4000" required></textarea></label><label><input type="checkbox" name="retention_confirmed" value="1"> Ich habe offene Verträge, weitere Datensysteme, Rechtsgrundlagen und Aufbewahrungsfristen geprüft. Erhaltene Finanz-/Vertragsdaten werden gesondert zweckgebunden verwaltet.</label><button class="button" type="submit">Prüfentscheidung speichern</button></form><?php endif;?></section><?php endforeach;?><?php if(!$requests):?><section class="panel"><p>Keine Anträge vorhanden.</p></section><?php endif;?></div></div></main><?php include __DIR__.'/../includes/footer.php';?>
